# -*- coding: utf-8 -*-
import time
from pinpong.board import gboard, I2C

class LIS2DH:
    LIS2DH12_RANGE_2GA      = 0x00
    LIS2DH12_RANGE_4GA      = 0x10
    LIS2DH12_RANGE_8GA      = 0x20
    LIS2DH12_RANGE_16GA     = 0x30

    def __init__(self, board=None, i2c_addr=0x1d, bus_num=4):
        if isinstance(board, int):
            i2c_addr = board
            board = gboard
        elif board is None:
            board = gboard
        
        self.board = board
        self.i2c_addr = i2c_addr
        self.i2c = I2C(bus_num)
        self.x = 0
        self.y = 0
        self.z = 0

    def init(self, range_val):
        self.set_range(range_val)
    
    # Liga o sensor (100Hz, eixos XYZ)
        self.write_reg(0x20, 0x2F) 
    
    # Define a escala (range)
        self.write_reg(0x23, range_val)
    
        self.init_vibracao()

        time.sleep(0.1)
        return True


    def init_vibracao(self):
    # CTRL_REG1 (0x20): 1.344kHz, Eixos XYZ ligados -> 0x97
        self.write_reg(0x20, [0x97])
    
    # CTRL_REG4 (0x23): +/- 4g, Alta Resolucao (HR) ligada -> 0x18
    # (0x10 do range + 0x08 do HR)
        self.write_reg(0x23, [0x18])
    
    # Atualiza a escala interna para calculo (4g HR = 2mg/digito)
        self.scale_factor = 2

    def read_XYZ(self):
        data = self.read_reg(0xA8, 6)
        if len(data) < 6: return

        def decode_int16(low, high):
        # Combina os bytes
            combined = (high << 8) | low
        # Converte para inteiro com sinal (16 bits)
            if combined > 32767:
                combined -= 65536
        
        # IMPORTANTE: O LIS3DH no modo normal (10-bit) 
        # armazena o dado nos bits superiores. Precisamos deslocar 6 bits.
            return combined >> 6

    # Sensibilidade para 2G no modo 10-bit (Normal) eh 4mg/digito
    # Se o sensor estiver em High Resolution (12-bit), mude para >> 4 e 1mg/digito
        raw_x = decode_int16(data[0], data[1])
        raw_y = decode_int16(data[2], data[3])
        raw_z = decode_int16(data[4], data[5])

    # No modo Normal 2G, multiplicamos o valor bruto por 4 para ter mg
        self.x = raw_x * 4
        self.y = raw_y * 4
        self.z = raw_z * 4

    def set_range(self, range_val):
        if range_val == self.LIS2DH12_RANGE_2GA: self.scale_vel = 16
        elif range_val == self.LIS2DH12_RANGE_4GA: self.scale_vel = 8
        elif range_val == self.LIS2DH12_RANGE_8GA: self.scale_vel = 4
        elif range_val == self.LIS2DH12_RANGE_16GA: self.scale_vel = 2
        else: self.scale_vel = 16

    def write_reg(self, reg, data):
    # Se data for um inteiro (ex: 0x2F), transformamos em lista [0x2F]
        if isinstance(data, int):
           data = [data]
    # Agora a PinPong conseguira iterar sobre o dado
        self.i2c.writeto_mem(self.i2c_addr, reg, data)

    def read_reg(self, reg, lens):
        # 0x80 eh o bit de leitura multipla no LIS2DH
        return self.i2c.readfrom_mem(self.i2c_addr, reg, lens)
